// Work out free start times for one day. Runs once for all items.
// Input items: booking rows for the requested date (may be a single empty item).
const CLINIC = {
  tz: 'Africa/Addis_Ababa',
  therapists: ['Amina', 'Daniel', 'Sara'],
  // ISO weekday (1 = Monday) -> [first start hour, last start hour]. Sunday missing = closed.
  hours: { 1: [9, 16], 2: [9, 16], 3: [9, 16], 4: [9, 16], 5: [9, 16], 6: [9, 12] },
  maxDaysAhead: 30,
};
const out = (httpStatus, reply) => [{ json: { httpStatus, reply } }];

const body = $('Check availability').first().json.body || {};
const date = String(body.date || '').trim();
const wanted = String(body.therapist || '').trim();
if (!date) return out(400, { error: 'date is required, as YYYY-MM-DD.' });

const day = DateTime.fromISO(date, { zone: CLINIC.tz });
if (!day.isValid || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return out(400, { error: `"${date}" is not a date. Use YYYY-MM-DD.` });

const today = DateTime.now().setZone(CLINIC.tz).startOf('day');
const daysAhead = Math.round(day.startOf('day').diff(today, 'days').days);
const weekday = day.toFormat('cccc');
const closed = (message) => out(200, { date, weekday, open: false, free: [], message });

if (daysAhead < 1) return closed('We can only book from tomorrow onwards.');
if (daysAhead > CLINIC.maxDaysAhead) return closed(`We only book up to ${CLINIC.maxDaysAhead} days ahead.`);
const range = CLINIC.hours[day.weekday];
if (!range) return closed(`The clinic is closed on ${weekday}s.`);

let therapists = CLINIC.therapists;
if (wanted) {
  const match = CLINIC.therapists.find(t => t.toLowerCase() === wanted.toLowerCase());
  if (!match) return out(200, { date, weekday, open: true, free: [], message: `We have no therapist called ${wanted}. Our therapists are ${CLINIC.therapists.join(', ')}.` });
  therapists = [match];
}

const booked = $input.all().map(i => i.json).filter(r => r.date === date && r.status === 'booked');
const free = [];
for (let h = range[0]; h <= range[1]; h++) {
  const time = `${String(h).padStart(2, '0')}:00`;
  const taken = booked.filter(r => r.time === time).map(r => r.therapist);
  const available = therapists.filter(t => !taken.includes(t));
  if (available.length) free.push({ time, therapists: available });
}

return out(200, {
  date, weekday, open: true, therapist: wanted ? therapists[0] : null, free,
  message: free.length ? `${free.length} start times free on ${weekday} ${date}. Appointments last 45 minutes.` : `Fully booked on ${weekday} ${date}.`,
});

// Decide whether a booking can go ahead. Runs once for all items.
// Input items: booking rows for the requested date (may be a single empty item).
// Output: { book, httpStatus, row?, reply }. The insert only runs when book is true.
const CLINIC = {
  tz: 'Africa/Addis_Ababa',
  therapists: ['Amina', 'Daniel', 'Sara'],
  hours: { 1: [9, 16], 2: [9, 16], 3: [9, 16], 4: [9, 16], 5: [9, 16], 6: [9, 12] },
  maxDaysAhead: 30,
};
const no = (httpStatus, reply) => [{ json: { book: false, httpStatus, reply } }];

const body = $('Book appointment').first().json.body || {};
const date = String(body.date || '').trim();
let time = String(body.time || '').trim();
const wanted = String(body.therapist || '').trim();
const patientName = String(body.patientName || '').trim().slice(0, 80);
const phone = String(body.phone || '').replace(/[\s()-]/g, '');

const missing = [['date', date], ['time', time], ['patientName', patientName], ['phone', phone]].filter(([, v]) => !v).map(([k]) => k);
if (missing.length) return no(400, { booked: false, error: `Missing: ${missing.join(', ')}.` });
if (!/^\+?\d{7,15}$/.test(phone)) return no(400, { booked: false, error: `"${body.phone}" doesn't look like a phone number.` });
const tm = time.match(/^(\d{1,2}):(\d{2})$/);
if (!tm) return no(400, { booked: false, error: `"${time}" is not a time. Use HH:MM, 24-hour.` });
time = `${tm[1].padStart(2, '0')}:${tm[2]}`;

const day = DateTime.fromISO(date, { zone: CLINIC.tz });
if (!day.isValid || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return no(400, { booked: false, error: `"${date}" is not a date. Use YYYY-MM-DD.` });

const today = DateTime.now().setZone(CLINIC.tz).startOf('day');
const daysAhead = Math.round(day.startOf('day').diff(today, 'days').days);
const weekday = day.toFormat('cccc');
const range = CLINIC.hours[day.weekday];

let therapists = CLINIC.therapists;
if (wanted) {
  const match = CLINIC.therapists.find(t => t.toLowerCase() === wanted.toLowerCase());
  if (!match) return no(200, { booked: false, alternatives: [], message: `We have no therapist called ${wanted}. Our therapists are ${CLINIC.therapists.join(', ')}.` });
  therapists = [match];
}

const booked = $input.all().map(i => i.json).filter(r => r.date === date && r.status === 'booked');
const freeAt = (t, who) => who.filter(th => !booked.some(r => r.time === t && r.therapist === th));
const slots = range ? Array.from({ length: range[1] - range[0] + 1 }, (_, i) => `${String(range[0] + i).padStart(2, '0')}:00`) : [];

// Up to three nearby options: same time with another therapist first, then other times.
const alternatives = () => {
  const alts = [];
  if (wanted) freeAt(time, CLINIC.therapists).forEach(th => alts.push({ date, time, therapist: th }));
  const order = slots.slice().sort((a, b) => Math.abs(parseInt(a) - parseInt(time)) - Math.abs(parseInt(b) - parseInt(time)));
  for (const t of order) { if (t !== time) { const f = freeAt(t, therapists); if (f.length) alts.push({ date, time: t, therapist: f[0] }); } }
  return alts.slice(0, 3);
};

if (daysAhead < 1) return no(200, { booked: false, alternatives: [], message: 'We can only book from tomorrow onwards.' });
if (daysAhead > CLINIC.maxDaysAhead) return no(200, { booked: false, alternatives: [], message: `We only book up to ${CLINIC.maxDaysAhead} days ahead.` });
if (!range) return no(200, { booked: false, alternatives: [], message: `The clinic is closed on ${weekday}s.` });
if (!slots.includes(time)) return no(200, { booked: false, alternatives: alternatives(), message: `Appointments on ${weekday}s start on the hour between ${slots[0]} and ${slots[slots.length - 1]}.` });

// One caller can't be in two appointments at once.
const clash = booked.find(r => r.time === time && String(r.phone || '').replace(/[\s()-]/g, '') === phone);
if (clash) return no(200, { booked: false, alternatives: [], message: `This phone number already has an appointment at ${time} on ${weekday} ${date} with ${clash.therapist}, reference ${clash.bookingId}.` });

const free = freeAt(time, therapists);
if (!free.length) {
  const who = wanted ? therapists[0] : 'any therapist';
  return no(200, { booked: false, alternatives: alternatives(), message: `${time} on ${weekday} ${date} is already taken for ${who}.` });
}

const therapist = free[0];
const bookingId = `NG-${date.replace(/-/g, '').slice(2)}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
return [{ json: {
  book: true,
  httpStatus: 200,
  row: { bookingId, date, time, therapist, patientName, phone, status: 'booked', source: String(body.source || 'voice-agent').slice(0, 40) },
  reply: { booked: true, bookingId, date, weekday, time, therapist, message: `Booked with ${therapist} on ${weekday} ${date} at ${time}. Reference ${bookingId}.` },
} }];

// Runs right after our booking row is saved, on a fresh read of every booking that day.
// Two callers can pass the "is it free?" check at the same moment and both save a row.
// Rule: the row saved first (lowest id) keeps the slot; every later one undoes itself.
const CLINIC = {
  tz: 'Africa/Addis_Ababa',
  therapists: ['Amina', 'Daniel', 'Sara'],
  hours: { 1: [9, 16], 2: [9, 16], 3: [9, 16], 4: [9, 16], 5: [9, 16], 6: [9, 12] },
};
const mine = $('Decide booking').first().json.row;
const all = $input.all().map(i => i.json).filter(r => r.date === mine.date && r.status === 'booked');
const sameSlot = all.filter(r => r.time === mine.time && r.therapist === mine.therapist).sort((a, b) => a.id - b.id);
const me = sameSlot.find(r => r.bookingId === mine.bookingId);

if (!me || sameSlot[0].bookingId === mine.bookingId) return [{ json: { won: true } }];

// We lost. Offer what is still free, ignoring our own row (it is about to be undone).
const taken = all.filter(r => r.bookingId !== mine.bookingId);
const isFree = (time, th) => !taken.some(r => r.time === time && r.therapist === th);
const day = DateTime.fromISO(mine.date, { zone: CLINIC.tz });
const [first, last] = CLINIC.hours[day.weekday] || [9, 16];
const hour = parseInt(mine.time, 10);
const alternatives = [];
CLINIC.therapists.filter(th => th !== mine.therapist && isFree(mine.time, th))
  .forEach(th => alternatives.push({ date: mine.date, time: mine.time, therapist: th }));
for (const d of [1, -1, 2, -2, 3, -3]) {
  const h = hour + d;
  const t = `${String(h).padStart(2, '0')}:00`;
  if (h >= first && h <= last && isFree(t, mine.therapist)) alternatives.push({ date: mine.date, time: t, therapist: mine.therapist });
}
return [{ json: {
  won: false,
  undoRowId: me.id,
  reply: { booked: false, alternatives: alternatives.slice(0, 3),
           message: `Sorry, ${mine.time} with ${mine.therapist} on ${day.toFormat('cccc')} ${mine.date} was just taken by another caller.` },
} }];

// Decide which booking to cancel. Runs once for all items.
// Input items: booking rows for the requested date (may be a single empty item).
// A booking is only cancelled when the caller's phone matches it, so nobody can cancel someone else's.
// Output: { cancel, httpStatus, rowId?, reply }. The update only runs when cancel is true.
const no = (httpStatus, reply) => [{ json: { cancel: false, httpStatus, reply } }];
const normPhone = (p) => String(p || '').replace(/[\s()-]/g, '');

const body = $('Cancel appointment').first().json.body || {};
const phone = normPhone(body.phone);
const date = String(body.date || '').trim();
let time = String(body.time || '').trim();
const therapist = String(body.therapist || '').trim().toLowerCase();

const missing = [['phone', phone], ['date', date]].filter(([, v]) => !v).map(([k]) => k);
if (missing.length) return no(400, { cancelled: false, error: `Missing: ${missing.join(', ')}.` });
if (time) {
  const tm = time.match(/^(\d{1,2}):(\d{2})$/);
  if (!tm) return no(400, { cancelled: false, error: `"${time}" is not a time. Use HH:MM, 24-hour.` });
  time = `${tm[1].padStart(2, '0')}:${tm[2]}`;
}

const mine = $input.all().map(i => i.json)
  .filter(r => r.date === date && r.status === 'booked' && normPhone(r.phone) === phone && (!time || r.time === time)
    && (!therapist || String(r.therapist).toLowerCase() === therapist));

if (mine.length === 0) {
  return no(200, { cancelled: false, message: `I can't find a booking for that phone number on ${date}${time ? ' at ' + time : ''}.` });
}
if (mine.length > 1) {
  const times = mine.map(r => `${r.time} with ${r.therapist}`).join(' and ');
  return no(200, { cancelled: false, message: `There are ${mine.length} bookings for that number on ${date}: ${times}. Which time should I cancel?` });
}

const b = mine[0];
return [{ json: {
  cancel: true,
  httpStatus: 200,
  rowId: b.id,
  reply: { cancelled: true, bookingId: b.bookingId, date: b.date, time: b.time, therapist: b.therapist,
           message: `Cancelled the ${b.time} appointment with ${b.therapist} on ${b.date}. Reference ${b.bookingId}.` },
} }];
